import React, {
  forwardRef,
  MouseEventHandler,
  PropsWithChildren,
  ReactNode,
} from "react";
import clsx from "clsx";
import { Button as ButtonStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

type Variants =
  | "primary"
  | "secondary"
  | "ghost"
  | "ghostNegative"
  | "success"
  | "warning"
  | "error";

type Props = PropsWithChildren<{
  /**
   * Pass true to disable the button
   * @default false
   */
  disabled?: boolean;
  /** Icon component */
  icon?: ReactNode;
  /** Button click handler */
  onClick?: MouseEventHandler<HTMLButtonElement>;
  /** Toggle button and set aria-pressed accordingly */
  pressed?: boolean;
  /**
   * The size of the button<br />
   * `extra-small` and `extra-large` sizes are replaced with `xsmall` and `xlarge`
   * @default medium
   */
  size?: "xsmall" | "small" | "medium" | "large" | "xlarge";
  /**
   * same as type in button element
   * @default "button"
   */
  type?: "button" | "submit" | "reset" | undefined;
  /**
   * The variant of the button
   * @default secondary
   */
  variant?: Variants;
}>;

export type ButtonProps = Props & CommonProps;

const useStyles = createUseStyles(ButtonStyles, "button");

export const Button = (
  props: ButtonProps,
  ref: React.Ref<HTMLButtonElement>
) => {
  const {
    variant = "secondary",
    size,
    icon,
    children,
    className,
    pressed,
    type = "button",
    ...rest
  } = props;
  const classes = useStyles();

  return (
    <button
      ref={ref}
      type={type}
      className={clsx(
        className,
        classes.root,
        variant && classes[`_${variant}`],
        size && classes[`_${size}`]
      )}
      aria-pressed={pressed}
      {...rest}
    >
      {icon}
      {children}
    </button>
  );
};

export default forwardRef<HTMLButtonElement, ButtonProps>(Button);
